/**
 * ANALYTICS query 10 ({@code COUNT(DISTINCT ?node) WHERE { ?node ?p ?o . FILTER EXISTS { ?s ?q ?node } }}) regressed
 * 25x on 2026-08-16 because the EXISTS placeable-mask fold made the plan eligible for the prefix-run recognizer, and
 * {@code LmdbNativeAggregatePlanner.compileAggregate} only attempts the exists-intersection recognizer when prefix-run
 * matched nothing — so the candidate that answers the query from two index cursors (80 ms) was never proposed and a
 * 13.8M-row masked scan (2016 ms) ran instead. The intersection recognizer is strictly narrower and strictly cheaper
 * when it matches, so it must be tried first. This test asserts the shape routes to {@code existsIntersection} again on
 * both janino arms, with the exact count.
 */
class LmdbKernelExistsIntersectTest {

	private static final String NS = "http://example.com/analytics/";

	private static final String QUERY = String.join("\n",
			"SELECT (COUNT(DISTINCT ?node) AS ?count) WHERE {",
			"  ?node ?p ?o .",
			"  FILTER EXISTS { ?s ?q ?node . }",
			"}");

	@ParameterizedTest(name = "janinoEnabled={0}")
	@ValueSource(strings = { "false", "true" })
	void existsIntersectionAnswersTheDistinctNodeCount(String janinoEnabled, @TempDir Path dataDir) throws Exception {
		String previousEnabled = System.getProperty("rdf4j.lmdb.janinoCodegen.enabled");
		String previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		String previousSynchronous = System.getProperty("rdf4j.lmdb.janinoCodegen.synchronous");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", janinoEnabled);
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		try {
			LmdbStore store = new LmdbStore(dataDir.resolve("analytics").toFile(),
					new LmdbStoreConfig("spoc,ospc,psoc,posc"));
			SailRepository repository = new SailRepository(store);
			try {
				ValueFactory values = SimpleValueFactory.getInstance();
				IRI type = values.createIRI(NS, "Entity");
				IRI links = values.createIRI(NS, "linksTo");
				try (SailRepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.NONE);
					// 60 entities are subjects (each has a type triple); entities 0..39 are additionally the
					// OBJECT of a linksTo triple, so exactly 40 subjects survive the EXISTS.
					for (int i = 0; i < 60; i++) {
						IRI entity = values.createIRI(NS, "entity-" + i);
						connection.add(entity, RDF.TYPE, type);
						if (i < 40) {
							connection.add(values.createIRI(NS, "referrer-" + i), links, entity);
						}
					}
					connection.commit();
				}
				// The referrers themselves are subjects too, and none of them is referenced: expected distinct
				// nodes with at least one outgoing triple AND at least one incoming reference = entities 0..39.
				try (SailRepositoryConnection connection = repository.getConnection();
						TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
					long count = ((org.eclipse.rdf4j.model.Literal) result.next().getValue("count")).longValue();
					Assertions.assertEquals(40L, count, "distinct referenced subjects, janinoEnabled=" + janinoEnabled);
				}
				try (SailRepositoryConnection connection = repository.getConnection()) {
					String plan = connection.prepareTupleQuery(QUERY)
							.explain(Explanation.Level.Executed)
							.toString();
					Assertions.assertTrue(plan.contains("existsIntersection"),
							"the exists-intersection candidate must be planned and executed for this shape"
									+ " (janinoEnabled=" + janinoEnabled + ") but the executed plan was:\n" + plan);
				}
			} finally {
				repository.shutDown();
			}
		} finally {
			restore("rdf4j.lmdb.janinoCodegen.enabled", previousEnabled);
			restore("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
			restore("rdf4j.lmdb.janinoCodegen.synchronous", previousSynchronous);
		}
	}

	private static void restore(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}
}
